FK.lang = 'pt-BR';
/** Traduz uma chave com placeholders. Cai para pt-BR e, por fim, para a própria chave. */
FK.t = function (key, vars) {
  let s = (FK.STRINGS[FK.lang] && FK.STRINGS[FK.lang][key]) || FK.STRINGS['pt-BR'][key] || key;
  if (vars) for (const k in vars) s = s.split('{' + k + '}').join(vars[k]);
  return s;
};
/** Aplica traduções a elementos com data-i18n, data-i18n-title, data-i18n-aria e data-i18n-ph. */
FK.applyI18n = function (root) {
  root = root || document;
  root.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = FK.t(el.dataset.i18n); });
  root.querySelectorAll('[data-i18n-title]').forEach(el => {
    const v = FK.t(el.dataset.i18nTitle); el.title = v; if (!el.hasAttribute('data-i18n-aria')) el.setAttribute('aria-label', v);
  });
  root.querySelectorAll('[data-i18n-aria]').forEach(el => el.setAttribute('aria-label', FK.t(el.dataset.i18nAria)));
  root.querySelectorAll('[data-i18n-ph]').forEach(el => { el.placeholder = FK.t(el.dataset.i18nPh); });
  document.documentElement.lang = FK.lang;
};

